sketch.css:
.tsb{position:relative;box-sizing:border-box;width:100%;height:100%;display:flex;flex-direction:column;gap:8px;padding:10px 12px;background:var(--window);color:var(--text);font:12px/1.35 "Segoe UI",system-ui,sans-serif;overflow:hidden}
.tsb *{box-sizing:border-box}
.head{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.title{font-size:13px;font-weight:600;flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.counts{display:flex;gap:10px;flex-wrap:wrap}
.count{display:flex;align-items:center;gap:5px;font-size:11.5px;color:var(--muted)}
.count b{color:var(--text);font-weight:600}
.swatch{width:8px;height:8px;border-radius:2px}
.swatch.booked{background:var(--window);border:1px solid var(--muted)}
.swatch.loading{background:var(--accent)}
.swatch.done{background:var(--background);border-left:3px solid var(--positive)}
.swatch.late{background:var(--negative)}
.free{display:flex;align-items:baseline;gap:4px;padding:1px 8px;border-radius:10px;background:var(--background)}
.free-value{font-weight:600;font-size:12px}
.free-label{font-size:11.5px;color:var(--muted)}
.scroller{flex:1;min-height:0;overflow-x:auto;overflow-y:auto;border-top:1px solid var(--border)}
.board{min-width:380px;height:100%;display:flex;flex-direction:column}
.axis{display:flex;height:22px;flex:none}
.corner{width:92px;flex:none}
.hours{position:relative;flex:1}
.hour{position:absolute;top:5px;transform:translateX(-50%);font-size:10.5px;color:var(--muted);white-space:nowrap}
.hour.first{transform:none}
.hour.last{transform:translateX(-100%)}
.now-label{position:absolute;top:3px;transform:translateX(-50%);font-size:10px;font-weight:600;color:var(--negative);background:var(--window);padding:0 3px;border-radius:4px}
.bays{flex:1;display:flex;flex-direction:column;min-height:0}
.bay{flex:1 1 0;min-height:28px;max-height:48px;display:flex;border-bottom:1px solid var(--border)}
.bay-name{width:92px;flex:none;display:flex;align-items:center;padding-right:8px;font-weight:600;font-size:11.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.track{position:relative;flex:1}
.grid{position:absolute;top:0;bottom:0;width:1px;background:var(--border)}
.now{position:absolute;top:0;bottom:0;width:2px;margin-left:-1px;background:var(--negative);z-index:2;pointer-events:none}
.slot{position:absolute;top:3px;bottom:3px;display:flex;align-items:center;gap:5px;padding:0 6px 0 3px;border-radius:6px;overflow:hidden;cursor:pointer;white-space:nowrap;z-index:1;border:1px solid transparent}
.slot.booked{background:var(--window);border-color:var(--muted);color:var(--text)}
.slot.loading{background:var(--accent);color:#fff}
.slot.done{background:var(--background);border-left:3px solid var(--positive);color:var(--muted)}
.slot.late{background:var(--negative);color:#fff}
.slot:hover{filter:brightness(1.06);box-shadow:0 1px 4px var(--border)}
.slot.selected{box-shadow:0 0 0 2px var(--text)}
.mot{flex:none;width:15px;height:15px;border-radius:4px;display:flex;align-items:center;justify-content:center;font-size:9.5px;font-weight:700;background:var(--background);color:var(--text)}
.slot.loading .mot,.slot.late .mot{background:var(--window);color:var(--text)}
.cp{font-weight:600;overflow:hidden;text-overflow:ellipsis;min-width:0}
.product{opacity:.8;overflow:hidden;text-overflow:ellipsis;min-width:0}
.empty{padding:24px 0;text-align:center;color:var(--muted)}
.tip{position:absolute;display:none;z-index:5;pointer-events:none;background:var(--text);color:var(--window);padding:6px 9px;border-radius:6px;font-size:11.5px;line-height:1.45;white-space:nowrap}
.tip b{font-weight:600}

sketch.js:
function render(root, props, fire) {
  var STATUS = [
    { key: "booked", text: "Booked" }, { key: "loading", text: "Loading" },
    { key: "done", text: "Done" }, { key: "late", text: "Late" }];
  var MOTS = { R: "Rail", T: "Truck", B: "Barge", P: "Pipeline" };
  function esc(s) { return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) { return "&#" + c.charCodeAt(0) + ";"; }); }
  function mins(t) { var m = /^(\d{1,2}):(\d{2})$/.exec(String(t || "").trim()); return m ? +m[1] * 60 + +m[2] : null; }
  function motKey(m) { var c = String(m || "").trim().charAt(0).toUpperCase(); return MOTS[c] ? c : "T"; }
  function statusKey(s) { s = String(s || "").toLowerCase(); for (var i = 0; i < STATUS.length; i++) if (STATUS[i].key === s) return s; return "booked"; }

  var start = Math.max(0, Math.min(23, props.startHour | 0));
  var end = Math.max(start + 1, Math.min(24, props.endHour | 0));
  var from = start * 60, to = end * 60, span = to - from;
  var pct = function (m) { return (Math.max(from, Math.min(to, m)) - from) / span * 100; };

  var slots = [], bays = [];
  (props.slots || []).forEach(function (s) {
    var a = mins(s.start), b = mins(s.end);
    if (!s.id || a == null || b == null || b <= a) return;
    var bay = String(s.bay || "—");
    if (bays.indexOf(bay) < 0) bays.push(bay);
    slots.push({ id: String(s.id), bay: bay, a: a, b: b, start: s.start, end: s.end, cp: s.counterparty || "", product: s.product || "", mot: motKey(s.mot), status: statusKey(s.status) });
  });

  root.querySelector(".title").textContent = props.title || "";

  var counts = { booked: 0, loading: 0, done: 0, late: 0 };
  slots.forEach(function (s) { counts[s.status]++; });
  root.querySelector(".counts").innerHTML = STATUS.map(function (st) {
    return "<span class='count'><span class='swatch " + st.key + "'></span>" + st.text + " <b>" + counts[st.key] + "</b></span>";
  }).join("");

  // free capacity: bay-hours inside the window not covered by any slot (overlaps merged)
  var used = 0;
  bays.forEach(function (bay) {
    var iv = slots.filter(function (s) { return s.bay === bay; })
      .map(function (s) { return [Math.max(from, s.a), Math.min(to, s.b)]; })
      .filter(function (x) { return x[1] > x[0]; })
      .sort(function (x, y) { return x[0] - y[0]; });
    var cs = -1, ce = -1;
    iv.forEach(function (x) { if (x[0] > ce) { if (ce > cs) used += ce - cs; cs = x[0]; ce = x[1]; } else ce = Math.max(ce, x[1]); });
    if (ce > cs) used += ce - cs;
  });
  var total = bays.length * span;
  root.querySelector(".free-value").textContent = total ? Math.round((1 - used / total) * 100) + "%" : "—";

  var nowM = mins(props.now);
  var showNow = nowM != null && nowM >= from && nowM <= to;

  var hours = "";
  for (var h = start; h <= end; h++) {
    var step = span > 12 * 60 ? 2 : 1;
    if ((h - start) % step && h !== end) continue;
    var cls = h === start ? " first" : h === end ? " last" : "";
    hours += "<span class='hour" + cls + "' style='left:" + pct(h * 60) + "%'>" + (h < 10 ? "0" : "") + h + ":00</span>";
  }
  if (showNow) hours += "<span class='now-label' style='left:" + pct(nowM) + "%'>" + esc(props.now) + "</span>";
  root.querySelector(".hours").innerHTML = hours;

  var grid = "";
  for (var h = start + 1; h < end; h++) grid += "<div class='grid' style='left:" + pct(h * 60) + "%'></div>";

  var html = "";
  if (!bays.length) html = "<div class='empty'>No slots booked</div>";
  bays.forEach(function (bay) {
    html += "<div class='bay'><div class='bay-name' title='" + esc(bay) + "'>" + esc(bay) + "</div><div class='track'>" + grid;
    slots.forEach(function (s) {
      if (s.bay !== bay || s.b <= from || s.a >= to) return;
      var l = pct(s.a), w = pct(s.b) - l;
      html += "<div class='slot " + s.status + (s.id === props.selected ? " selected" : "") + "' data-id='" + esc(s.id) + "' style='left:calc(" + l + "% + 1px);width:calc(" + w + "% - 2px)'>" +
        "<span class='mot'>" + s.mot + "</span><span class='cp'>" + esc(s.cp) + "</span><span class='product'>" + esc(s.product) + "</span></div>";
    });
    if (showNow) html += "<div class='now' style='left:" + pct(nowM) + "%'></div>";
    html += "</div></div>";
  });
  var baysEl = root.querySelector(".bays");
  baysEl.innerHTML = html;

  var tip = root.querySelector(".tip"), box = root.querySelector(".tsb");
  var byId = {}; slots.forEach(function (s) { byId[s.id] = s; });
  baysEl.querySelectorAll(".slot").forEach(function (el) {
    var s = byId[el.getAttribute("data-id")];
    el.onmouseenter = function () {
      var st = STATUS.filter(function (x) { return x.key === s.status; })[0].text;
      tip.innerHTML = "<b>" + esc(s.bay) + "</b> · " + esc(s.start) + "–" + esc(s.end) + "<br>" + esc(s.cp) + " · " + esc(s.product) + "<br>" + MOTS[s.mot] + " · " + st;
      tip.style.display = "block";
    };
    el.onmousemove = function (e) {
      var r = box.getBoundingClientRect();
      var x = e.clientX - r.left + 12, y = e.clientY - r.top + 14;
      if (x + tip.offsetWidth > r.width) x = r.width - tip.offsetWidth - 4;
      if (y + tip.offsetHeight > r.height) y = e.clientY - r.top - tip.offsetHeight - 10;
      tip.style.left = x + "px"; tip.style.top = y + "px";
    };
    el.onmouseleave = function () { tip.style.display = "none"; };
    el.onclick = function () { if (s.id !== props.selected) fire("slotSelected", { id: s.id, selected: s.id }); };
  });
}
